<?php
/**
 * Code Snippets: CY speed v4 (us + de credityup). Settings: "Only run on site front-end".
 * 1) Delays GTM-573CZ7M5, gtag (GA4) and the FB pixel until the 1st interaction (scroll/touch/click/key) or 3s after navigation start.
 *    Nothing is removed: the inline dataLayer/gtag/fbq snippets still run right away and queue events; only the external .js files wait.
 * 2) CLS: reserves 300px for content ad blocks (.winup-ad-block); fonts via swap.
 * 3) Logo: 118 KB PNG -> inline 150x100 WebP (~7 KB). relacio4.jpg (Rewarded popup) over https.
 * 4) Google Fonts: loads the CSS directly (display=swap, non-blocking) instead of the LiteSpeed webfontloader JS.
 * Does not touch wads.js, gpt.js, ad-engine, the Rewarded plugin or the auction.
 */
if (!function_exists('cy_speed_v4_filter')) {
function cy_speed_v4_filter($html, $host) {
    if (stripos($html, '<head') === false || strpos($html, 'cy-v4-delay') !== false) return $html;
    $logos = array(
        'us.credityup.com' => 'data:image/webp;base64,',
        'de.credityup.com' => 'data:image/webp;base64,',
    );
    $js = <<<'CYJS'
(function(w,d){var Q=[],go=0,re=/googletagmanager\.com\/(gtm\.js|gtag\/js)|connect\.facebook\.net\/[^\/]+\/fbevents/;function hold(o){return function(n,r){if(!go&&n&&n.tagName==='SCRIPT'&&re.test(n.src||'')){Q.push([this,n,r]);return n}return o.apply(this,arguments)}}var P=Node.prototype,AI=P.insertBefore,AC=P.appendChild;P.insertBefore=hold(AI);P.appendChild=hold(AC);var E=['scroll','touchstart','pointerdown','keydown','click','wheel','mousemove'];function run(){if(go)return;go=1;E.forEach(function(e){w.removeEventListener(e,run,{passive:true})});Q.forEach(function(q){try{AI.call(q[0],q[1],q[2]&&q[2].parentNode===q[0]?q[2]:null)}catch(e){AC.call(d.head,q[1])}});Q=[];[].forEach.call(d.querySelectorAll('script[type="cy/delay"]'),function(s){var n=d.createElement('script');n.async=true;n.src=s.getAttribute('data-src');AC.call(d.head,n)})}E.forEach(function(e){w.addEventListener(e,run,{passive:true})});setTimeout(run,Math.max(0,3000-(w.performance?performance.now():0)));w.cyDelayRun=run})(window,document);
CYJS;
    $head = '<script id="cy-v4-delay">' . $js . '</script>'
          . '<style id="cy-v4-css">.winup-ad-block{min-height:300px}</style>'
          . '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>';
    // right after <meta charset> (before the FB/GTM/GA4 snippets)
    $html = preg_replace('/(<meta charset=[^>]*>)/i', '$1' . $head, $html, 1, $n);
    if (!$n) $html = preg_replace('/(<head[^>]*>)/i', '$1' . $head, $html, 1);
    // gtag.js printed directly in the HTML -> delayed (the inline gtag() still queues into dataLayer)
    $html = str_replace('<script async src="https://www.googletagmanager.com/gtag/js?id=',
                        '<script type="cy/delay" data-src="https://www.googletagmanager.com/gtag/js?id=', $html);
    // Google Fonts: LiteSpeed's webfontloader (JS) -> direct CSS with swap, non-blocking
    $fonts = 'https://fonts.googleapis.com/css2?family=Roboto:wght@300;400;500;700&family=Roboto+Slab:wght@400;700&display=swap';
    $html = preg_replace('#<script>WebFontConfig=.*?webfontloader\.min\.js"></script>#s',
        '<link rel="preload" as="style" href="' . $fonts . '" onload="this.onload=null;this.rel=\'stylesheet\'"><noscript><link rel="stylesheet" href="' . $fonts . '"></noscript>', $html, 1);
    // Rewarded popup image over https
    $html = str_replace('data-ram-img-src="http://', 'data-ram-img-src="https://', $html);
    // Logo: inline WebP at the display size (75x50 @2x)
    if (isset($logos[$host])) {
        $html = preg_replace('#<img(\s+)src="https?://' . preg_quote($host, '#') . '/wp-content/uploads/[^"]*/cropped-[^"]+\.png"([^>]*)>#i',
            '<img$1src="' . $logos[$host] . '" width="150" height="100" decoding="async"$2>', $html, 1);
        $html = preg_replace('#(<img\s+src="data:image/webp[^"]*" width="150" height="100" decoding="async"[^>]*?)\s+width="\d+" height="\d+"#', '$1', $html, 1);
    }
    return $html;
}
}
if (function_exists('add_action')) {
    add_action('template_redirect', function () {
        if (is_admin() || wp_doing_ajax() || is_feed() || (defined('REST_REQUEST') && REST_REQUEST) || is_user_logged_in()) return;
        $host = isset($_SERVER['HTTP_HOST']) ? strtolower($_SERVER['HTTP_HOST']) : '';
        ob_start(function ($html) use ($host) { return cy_speed_v4_filter($html, $host); });
    }, 0);
}
